import numpy as np
def build_cycle(N, d1, blend=0.02):
    # asymmetric trapezoid: rise -1..+1 over d1, fall +1..-1 over rest, cosine-blended corners
    ph = np.arange(N)/N
    w = np.empty(N)
    # corner smoothing via tanh-free approach: define piecewise with cosine ramps
    def ramp(x):
        # 0..1 cosine smoothstep -1..1
        return -np.cos(np.pi*np.clip(x,0,1))
    for i, p in enumerate(ph):
        if p < d1:
            x = (p - blend/2)/(d1 - blend)
            w[i] = ramp(x) if x < 1 else 1.0
            if x < 0: w[i] = -1.0
        elif p < 0.5:
            w[i] = 1.0
        elif p < 0.5 + blend:
            w[i] = 1.0 - (1+ramp((p-0.5)/blend))*0  # placeholder
            w[i] = np.cos(np.pi*(p-0.5)/blend)
        elif p < 0.5 + (1-d1-0.5):
            x = (p - 0.5 - blend/2)/(0.5 - d1 + 0.5 - blend)  # fall segment
            w[i] = ramp(1-x) if (1-x) < 1 else -1.0
            if (1-x) < 0: w[i] = 1.0
        else:
            w[i] = -1.0
    return w
for N in (256, 152):
    for d1 in (0.1, 0.2, 0.3):
        w = build_cycle(N, d1)
        d = np.abs(np.diff(w))
        print(f"N={N} d1={d1}: peak {np.abs(w).max():.2f} maxdiff {d.max():.4f} A={125/d.max():.0f}")
EOF"}

